#!/usr/bin/env bun
/**
 * emit-theme-css — generate the three-block theme CSS
 * (`:root` + `[data-theme="light"]` + `[data-theme="dark"]`) from a ThemeSeed,
 * reusing the package's own `generateThemeCSS` (via the `_vendor` snapshot —
 * L9). This is the bridge that proves the seed actually reaches CSS: the seed
 * and the codegen move together, so they must be generated by the same math the
 * package publishes, not a hand-written approximation.
 *
 * The `--check` mode is the regen-staleness gate (L9): it regenerates from the
 * seed and compares to the committed CSS, exiting 1 on any drift. A green
 * `--check` is the evidence that the committed `theme.generated.css` is not
 * stale relative to its seed — the failure mode where a seed is edited but the
 * CSS isn't regenerated, so the running app silently shows old tokens.
 *
 * The timestamped/path header line the package emits is ignored in the compare,
 * since it changes every run and is not a token. Token content is what gates.
 *
 * CLI:
 *   emit-theme-css --seed <path> --out <css> [--check] [--json]
 *
 *   --seed <path>   a .ts/.json file exporting a ThemeSeed (default export, or
 *                   the first named export with primary + accent/accents).
 *   --out <css>     where to write (write mode) or compare against (--check).
 *   --check         do not write — exit 1 if --out is stale vs the seed.
 *   --json          machine-readable summary.
 *
 * Examples:
 *   emit-theme-css --seed ./lib/theme-seed.ts --out ./app/theme.generated.css
 *   emit-theme-css --seed ./lib/theme-seed.ts --out ./app/theme.generated.css --check
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

import {
  generateThemeCSS,
  type ThemeSeedInput,
} from '../_vendor/theme-math.ts';

interface Args {
  seed: string | null;
  out: string | null;
  check: boolean;
  json: boolean;
}

function parseArgs(argv: string[]): Args {
  const a: Args = { seed: null, out: null, check: false, json: false };
  for (let i = 0; i < argv.length; i++) {
    const flag = argv[i];
    if (flag === '--seed' && argv[i + 1]) a.seed = argv[++i];
    else if (flag === '--out' && argv[i + 1]) a.out = argv[++i];
    else if (flag === '--check') a.check = true;
    else if (flag === '--json') a.json = true;
  }
  return a;
}

function isSeedLike(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    'primary' in value &&
    ('accent' in value || 'accents' in value)
  );
}

/** Load a ThemeSeed from a .ts/.json module, mirroring the package CLI's resolution. */
export async function loadSeed(seedPath: string): Promise<ThemeSeedInput> {
  const abs = resolve(process.cwd(), seedPath);
  if (!existsSync(abs)) {
    throw new Error(`Seed file not found: ${abs}`);
  }
  const mod = (await import(pathToFileURL(abs).href)) as Record<string, unknown>;
  const seed = isSeedLike(mod.default)
    ? mod.default
    : Object.values(mod).find(isSeedLike);
  if (!seed) {
    throw new Error(
      `No ThemeSeed in ${seedPath} — expected a default export OR a named export with primary + accent/accents.`,
    );
  }
  return seed as unknown as ThemeSeedInput;
}

/**
 * Strip the generated header comment block so the compare is token-content
 * only. The package writes a `/* Generated from … at <ISO timestamp> … *​/`
 * banner that changes every run; comparing it would make every --check fail.
 */
export function stripHeader(css: string): string {
  return css.replace(/^\/\*[\s\S]*?\*\/\n*/, '').trim();
}

function main(): void {
  void (async () => {
    const args = parseArgs(process.argv.slice(2));
    if (!args.seed || !args.out) {
      console.error('Usage: emit-theme-css --seed <path> --out <css> [--check] [--json]');
      process.exit(1);
    }

    let seed: ThemeSeedInput;
    try {
      seed = await loadSeed(args.seed);
    } catch (err) {
      console.error(`✗ ${(err as Error).message}`);
      process.exit(1);
    }

    const css = generateThemeCSS(seed, {
      header: `Generated from ${args.seed} at ${new Date().toISOString()}. DO NOT EDIT — re-run emit-theme-css to regenerate.`,
    });

    const outPath = resolve(process.cwd(), args.out);

    if (args.check) {
      const onDisk = existsSync(outPath) ? readFileSync(outPath, 'utf8') : null;
      const stale = onDisk === null || stripHeader(onDisk) !== stripHeader(css);
      if (args.json) {
        console.log(JSON.stringify({ ok: !stale, stale, out: outPath, missing: onDisk === null }));
      } else if (!stale) {
        console.log(`✓ ${args.out} is in sync with ${args.seed}`);
      } else if (onDisk === null) {
        console.error(`✗ ${args.out} does not exist — regenerate from ${args.seed}`);
      } else {
        console.error(`✗ ${args.out} is STALE vs ${args.seed} (L9) — regenerate it`);
      }
      process.exit(stale ? 1 : 0);
    }

    writeFileSync(outPath, css);
    if (args.json) {
      console.log(JSON.stringify({ ok: true, out: outPath, lines: css.split('\n').length }));
    } else {
      console.log(`✓ wrote ${args.out} (${css.split('\n').length} lines)`);
    }
  })();
}

if (import.meta.main) {
  main();
}
